#
# Rule:        CKV2_AWS_11 (checkov 3.3.16)
# Applies to:  aws_vpc
# Read with:   aws_vpcs -> aws_flow_log (stock inspec-aws, no custom reader)
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV2_AWS_11'] || []

control 'CKV2_AWS_11' do
  title 'Ensure VPC flow logging is enabled in all VPCs'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_vpc resources that actually exist, read through the stock
    inspec-aws aws_flow_log resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Without a flow log there is no record of what talked to what inside the
    VPC. An intrusion is then reconstructible only from application logs,
    and lateral movement between instances — which never touches an
    application log — leaves no trace at all.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: a VPC that has a flow log attached to it, capturing
    accepted and rejected network traffic
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_vpc:

      resource "aws_flow_log" "main" {
        vpc_id                   = aws_vpc.main.id
        traffic_type             = "ALL"
        log_destination_type     = "cloud-watch-logs"
        log_destination          = aws_cloudwatch_log_group.flow.arn
        iam_role_arn             = aws_iam_role.flow_logs.arn
        max_aggregation_interval = 60
      }

    Out of band — aws_vpc:

      aws ec2 create-flow-logs --resource-type VPC --resource-ids <vpc-id> --traffic-type ALL --log-destination-type cloud-watch-logs --log-group-name <group> --deliver-logs-permission-arn <role-arn>

    Note (aws_vpc): Use traffic_type = "ALL": REJECT alone hides successful
    lateral movement and ACCEPT alone hides the scanning that preceded it. An S3
    or Data Firehose destination satisfies this control equally — it asserts
    that a flow log exists for the VPC, not where it lands.
  FIX

  tag checkov_id:            'CKV2_AWS_11'
  tag checkov_category:      'LOGGING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'graph'
  tag tf_resources:          %w[aws_vpc]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/vpc'
  tag nist:                  ['SI-4', 'AU-12']
  tag nist_r4:               ['SI-4', 'AU-12']
  tag cci:                   ['CCI-002664', 'CCI-000172']
  tag ksi:                   ['KSI-MLA-OSM']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_vpcs(aws_region: region).vpc_ids.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_vpc', rules: exempt) }

  if unusable.positive?
    describe "aws_vpc enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "          'likely names a field this resource does not expose'
      end
    end
  end

  # `unusable.positive?` keeps the control APPLICABLE when every id came back
  # blank. Without it only_if skips the control, and the wrong-column case this
  # guard exists to catch is exactly the case it would suppress — a Not
  # Applicable that means "the enumeration is broken".
  applicable = !in_scope.empty? || unusable.positive?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_vpc in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_flow_log(vpc_id: id, aws_region: region) do
      its('exists?') { should eq true }
    end
  end
end
